{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) < 2:
        raise ValueError("nodes must be a list with at least 2 elements")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be a dict")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Node {node!r} missing from core_distance")

    # Compute mutual reachability edges
    mr_edges = []
    for entry in distances:
        if len(entry) != 3:
            raise ValueError("Each distance entry must have exactly 3 elements")
        u, v, d = entry[0], entry[1], entry[2]
        if u not in core_distance:
            raise ValueError(f"Node {u!r} not in core_distance")
        if v not in core_distance:
            raise ValueError(f"Node {v!r} not in core_distance")
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize undirected endpoints lexicographically
        if u > v:
            u, v = v, u
        mr_edges.append((u, v, mr))

    # Sort by mutual reachability weight, then first endpoint, then second endpoint
    mr_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for u, v, w in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Input graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
